python -c "
import gzip
import pandas as pd
import numpy as np
import os

path = '/data/users/arao/mpra_autoresearch/data/dhs/DHS_Index_and_Vocabulary_hg38_WM20190703.txt.gz'
cols = ['seqname', 'start', 'end', 'mean_signal', 'summit', 'component']
print('Loading DHS data...')
df = pd.read_csv(gzip.open(path, 'rt'), sep='\t', usecols=cols)

# Load chromosomes helper
chrom_seqs = {}
def get_sequence(chrom, start, end):
    if chrom not in chrom_seqs:
        c_path = f'/data/users/arao/mpra_autoresearch/data/{chrom}.fa'
        if not os.path.exists(c_path):
            return None
        with open(c_path, 'r') as f:
            f.readline() # header
            chrom_seqs[chrom] = f.read().replace('\n', '').upper()
    seq = chrom_seqs[chrom][start:end]
    return seq

# QC helper
def passes_qc(seq):
    if not all(c in 'ACGT' for c in seq):
        return False
    gc = (seq.count('C') + seq.count('G')) / len(seq)
    if gc < 0.20 or gc > 0.80:
        return False
    for base in 'ACGT':
        if base * 13 in seq:
            return False
    return True

df_sorted = df.sort_values(by='mean_signal', ascending=False)
components = df['component'].unique()
selected_by_component = {comp: [] for comp in components}
selected_regions = {}

print('Filtering with QC...')
for idx, row in df_sorted.iterrows():
    comp = row['component']
    if len(selected_by_component[comp]) >= 3125:
        continue

    chrom = row['seqname']
    summit = int(row['summit'])
    start = summit - 100
    end = summit + 100

    if start < 0:
        continue

    # check overlap
    overlap = False
    if chrom in selected_regions:
        for s, e in selected_regions[chrom]:
            if max(start, s) < min(end, e):
                overlap = True
                break
    if overlap:
        continue

    seq = get_sequence(chrom, start, end)
    if seq is None or len(seq) != 200:
        continue

    if not passes_qc(seq):
        continue

    selected_by_component[comp].append(seq)
    if chrom not in selected_regions:
        selected_regions[chrom] = []
    selected_regions[chrom].append((start, end))

print('\nTotal selected with QC per component:')
total = 0
for comp, seqs in selected_by_component.items():
    print(f'{comp}: {len(seqs)}')
    total += len(seqs)
print('Grand total selected:', total)
"
